        foreach ($states as $stateData) {
            $state = State::create([
                'shipping_cost' => $stateData['shipping_cost'],
                'delivery_cost' => $stateData['delivery_cost'],
                'return_cost' => $stateData['return_cost'],
                'en' => ['name' => $stateData['en']],
                'fr' => ['name' => $stateData['fr']],
                'ar' => ['name' => $stateData['ar']],
            ]);

            foreach ($stateData['cities'] as $cityData) {
               $city = City::create([
                   'en' => ['name' => $cityData['en']],
                   'fr' => ['name' => $cityData['fr']],
                   'ar' => ['name' => $cityData['ar']],
                    'state_id' => $state->id
               ]);

                
                foreach ($cityData['localities'] as $localityData) {
                    $city->localities()->create([
                        'en' => ['name' => $localityData['en']],
                        'fr' => ['name' => $localityData['fr']],
                        'ar' => ['name' => $localityData['ar']],
                        'postal_code' => $localityData['postal_code']
                    ]);
    
    
                }
            }
        }
    }
